CREATE TABLE jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_profile_id uuid REFERENCES customer_profiles(id), quote_id uuid REFERENCES quotes(id), employee_profile_id uuid REFERENCES employee_profiles(id), initial_status text NOT NULL DEFAULT 'requested' CHECK (initial_status = 'requested'), created_by_user_id uuid NOT NULL REFERENCES users(id), idempotency_key uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(created_by_user_id, idempotency_key));
CREATE TABLE appointments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL UNIQUE REFERENCES jobs(id), window_start timestamptz NOT NULL, window_end timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK (window_end > window_start));
CREATE TABLE job_transitions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES jobs(id), from_status text NOT NULL, to_status text NOT NULL, actor_user_id uuid NOT NULL REFERENCES users(id), reason text, idempotency_key uuid NOT NULL, correlation_id uuid NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(actor_user_id, idempotency_key));
CREATE INDEX job_transitions_job_occurred_idx ON job_transitions (job_id, occurred_at DESC);
CREATE FUNCTION reject_job_transition_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Job transitions are immutable.'; END; $$;
CREATE TRIGGER job_transitions_immutable BEFORE UPDATE OR DELETE ON job_transitions FOR EACH ROW EXECUTE FUNCTION reject_job_transition_mutation();
